hints:
```
for each query q:
  for each dictionary word d:
    count positions i where q[i] != d[i]
    if count <= 2:
      add q to answer
      break
```

code.cpp:
class Solution {
public:
    vector<string> twoEditWords(vector<string>& queries, vector<string>& dictionary) {
        vector<string> result;
        for (const string& q : queries) {
            for (const string& d : dictionary) {
                int diff = 0;
                int n = (int)q.size();
                for (int i = 0; i < n; i++) {
                    if (q[i] != d[i]) {
                        diff++;
                        if (diff > 2) break;
                    }
                }
                if (diff <= 2) {
                    result.push_back(q);
                    break;
                }
            }
        }
        return result;
    }
};
